import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`investment-tracking`,heroTitle:`Optimize your portfolio in minutes`,heroSubtitle:`Perplexity Computer tracks your holdings, analyzes performance, and suggests improvements — automatically.`,inputUrlCta:`Track my portfolio`,inputUrlPlaceholder:`Risk tolerance (e.g. "low risk")`,inputUrlPrefill:`Connect my brokerage accounts and give me a full portfolio analysis. My investment approach is {url} — but ask me more questions to understand my risk tolerance and timeline. Then build me an investment dashboard. 1) Map my full portfolio — every holding, allocation, sector exposure, and fee structure across all accounts. 2) Identify overlap between ETFs, concentration risk, and any drift from my target allocation. 3) Calculate my actual dollar-weighted returns vs. what my brokerage reports. 4) Load current market data and flag high-conviction optimization opportunities. 5) Set up proactive alerts for rebalancing triggers, concentration warnings, and fee drag. Ask me how active I want to be and what kind of suggestions I’m open to.`,heroOverlaySteps:[`Connecting to your portfolio and pulling current holdings`,`Analyzing asset allocation, sector exposure, and fee drag`,`Benchmarking performance against major indices and peers`,`Rebalancing plan, tax-loss picks, and fee savings — ready to review`],generatingSteps:[`Visiting {url} to extract your holdings, balances, and allocation`,`Designing an agent to benchmark your portfolio and find optimization opportunities`,`Configuring performance tracking, fee analysis, and rebalancing logic`,`Setting up automated alerts for drift, tax-loss harvesting, and market shifts`],featureSectionTitle:`From holdings to action plan`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Plaid, Google Sheets, Notion, Gmail — Computer plugs into your tools so portfolio tracking, alerts, and reports happen in one workflow.`,`Holdings breakdown with gains and losses. Asset allocation heatmaps. Rebalancing trade lists. Tax-loss harvesting picks. Fee drag reports with cheaper alternatives.`],capabilitySectionTitle:`Your financial analyst, on autopilot`,capabilitySectionSubtitle:`Connect your portfolio, step away, get back a full optimization plan.`,capabilityCards:[{title:`Portfolio Analysis`,description:`Computer can break down your holdings by asset class, sector, and geography — and flag concentration risks before they become problems.`},{title:`Performance Tracking`,description:`Computer can benchmark your returns against the S&P 500, target-date funds, and custom indices — with attribution for what’s dragging or driving performance.`},{title:`Tax Optimization`,description:`Computer can scan your taxable accounts for tax-loss harvesting opportunities and estimate the savings — with specific sell-and-replace recommendations.`},{title:`Connect Your Tools`,description:`Computer can read from Plaid, Google Sheets, Notion, and more — build workflows across your entire financial stack.`},{title:`Remember & Learn`,description:`Computer can remember your risk tolerance, investment goals, and tax situation across sessions — so every recommendation builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch your allocation drift and market conditions daily — and ping you when it’s time to rebalance or harvest a loss.`}]});export{t as default};
